<script setup>
import { ref, computed } from 'vue'
import Icon from '../components/Icon.vue'
import Chart from '../components/Chart.vue'
import { deployments } from '../data'
const emit = defineEmits(['action'])
const period = ref('Last 4 hours'), all = ref(true)
const stats = [['Requests','2.8M','8.20%','analytics'],['Errors','0.28%','4.10%','alert'],['CPU Time','23.7 ms','1.30%','cpu'],['Wall Time','0.05 ms','6.80%','server'],['Execution Duration','2.4 GB-sec','1.19%','timer'],['Request Duration','23.7 ms','30.30%','globe']]
const series = (i) => Array.from({length:72},(_,n) => {
  const spikes = [[39,46,53,59,63,67,70],[48,55],[8,15,24,42,50,52,55,59,67],[3,42,49,55,61,67]][i]
  return i < 4 ? spikes.includes(n) ? 4 + ((n*17+i*7)%24) : 0 : n % 8 === i-4 ? 6 + ((n*17+i*7)%20) : 0
})
const displayed = computed(() => all.value ? deployments : deployments.slice(0,4))
</script>
<template><div class="dashboard dashboard-ten">
  <div class="observability-title"><div><Icon name="sun" :size="26"/><h1>Welcome back</h1></div><div class="flex"><select v-model="period" aria-label="Stats time range"><option>Last 4 hours</option><option>Last 24 hours</option><option>Last 7 days</option></select><button class="icon-button" aria-label="Dashboard options" @click="emit('action',{title:'Overview options',body:'Choose a time range to review your service performance.'})"><Icon name="more"/></button></div></div>
  <div class="observability-metrics"><section v-for="(stat,i) in stats" :key="stat[0]" class="observability-metric" :class="{'wide':i>3}"><div class="section-title"><h3><Icon :name="stat[3]" :size="13"/>{{stat[0]}}</h3><button class="text-button" :aria-label="stat[0] + ' details'" @click="emit('action',{title:stat[0],body:`${stat[0]}: ${stat[1]} over the ${period.toLowerCase()}. Performance changed ${stat[2]} compared with the previous window.`})"><Icon name="help" :size="12"/></button></div><div class="section-summary"><h2>{{period === 'Last 24 hours' && i === 0 ? '16.8M' : period === 'Last 7 days' && i === 0 ? '117.6M' : stat[1]}}</h2><small class="muted inline-icon"><Icon :name="i===1 || i===2 ? 'decrease' : 'up'" :size="12"/>{{stat[2]}}</small></div><Chart :values="series(i)" type="line" :max="35" :height="i > 3 ? 95 : 66" :grid="false"/></section></div>
  <div class="observability-insights grid two"><section class="ai-card"><div class="section-title"><h3><Icon name="activity"/>AI Insight</h3><button class="text-button" @click="emit('action',{title:'Deployment traces',body:'v2.8.1 reduced cold starts by 18% compared with the previous window. Edge cache invalidation improved after the latest deployment.'})"><Icon name="zap" :size="13"/>View traces</button></div><p class="insight-copy">Cold starts fell by <strong>18% in the {{period.toLowerCase()}}</strong> vs. the previous window after the v2.8.1 deploy.</p></section><section class="latency-card"><div class="section-title"><div><p>Latency distribution</p><h2>23.7 ms<small> p95</small></h2></div><button class="text-button" @click="emit('action',{title:'Latency metrics',body:'P50: 12.4ms (45%). P95: 23.7ms (35%). P99: 48.2ms (20%).'})"><Icon name="timer" :size="13"/>Open metrics</button></div><div class="distribution-labels"><span>45%</span><span>35%</span><span>20%</span></div><div class="distribution"><span style="flex:45;background:#d4d4d4"></span><span style="flex:35;background:#555"></span><span style="flex:20;background:#262626"></span></div><div class="legend"><span>P50</span><span>P95</span><span>P99</span></div></section></div>
  <section class="deployments"><div class="section-title"><h3><Icon name="server"/>Active deployments</h3><button class="text-button" @click="all = !all">{{all ? 'View all' : 'Show all 10'}}<Icon :name="all ? 'arrow' : 'down'" :size="13"/></button></div><div class="deployment-row" v-for="row in displayed" :key="row[0]"><div><h4>v{{row[0]}}</h4><small>{{row[1]}}</small></div><span class="deployment-status"><i class="status-dot" :class="row[2].toLowerCase()"></i>{{row[2]}}</span><div class="deployment-commit"><h4><Icon name="branch" :size="15"/>{{row[3]}}</h4><small>{{row[4]}}</small></div><span class="muted deployment-date">{{row[5]}}</span><span class="deployment-cache"><i class="status-dot" :class="row[6] === 'Cached' ? 'healthy' : 'warning'"></i>{{row[6]}}</span><button class="text-button" :aria-label="'Deployment v' + row[0] + ' actions'" @click="emit('action',{title:'Deployment v'+row[0],body:`${row[1]} · ${row[2]} · ${row[3]} · ${row[4]} · ${row[5]} · ${row[6]}`})"><Icon name="dots"/></button></div></section>
</div></template>
